# prompts.py - picture prompts for sunken-lunch (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
def tail(key='green'): return " Whole bodies in frame with a margin. " + CHAR + " " + KEY(key)

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the RIGHT, cheerful and excited: the arm on the RIGHT side of the image raised in front of the chest giving a big thumbs up, the other arm relaxed down at the side, eyebrows raised, eyes wide and happy, a big open smile with the pink tongue showing. Whole body in frame with a margin. Bold clean thick outlines, big simple shapes, few details. " + CHAR + " " + KEY()),
 'sheetA': ("3:2", ROW3 + "LEFT copy: facing the viewer, terrified: both arms flung straight up above the head with the open hands spread wide, eyes wide open, eyebrows tilted up in the middle, mouth wide open in a scream showing the pink tongue. MIDDLE copy: side view facing to the RIGHT, leaping in mid-air: the body stretched out diagonally in a big jump toward the upper right, both arms reaching forward and up to the RIGHT with open hands, both legs bent back behind the body, eyes squeezed shut, eyebrows angled down, mouth open in a brave shout. RIGHT copy: facing the viewer, jaw-dropping amazement: the mouth hanging wide open in a tall oval showing the pink tongue, eyes very wide, eyebrows raised very high, both hands pressed flat against the cheeks." + tail()),
 'sheetB': ("3:2", ROW3 + "LEFT copy: side view facing to the RIGHT, cranking a handle: knees a little bent, leaning forward, both hands closed into fists held together in front of the chest at chest height as if gripping a crank handle (no crank drawn), eyes squeezed shut, eyebrows angled down, teeth gritted in a wide flat grimace, straining. MIDDLE copy: facing the viewer, a smug know-it-all look: the hand on the RIGHT side of the image raised beside the head at head height with the fingers closed as if holding up a thin stick (holding nothing), the other hand resting on the hip, eyes half-closed, one eyebrow raised, a small confident closed smile. RIGHT copy: three-quarter view facing to the RIGHT, lowering something on a rope: standing upright, both arms stretched forward to the RIGHT at waist height with both hands closed into fists one just above the other as if holding a rope that hangs straight down (no rope drawn), looking down to the right, a happy proud smile with the eyes curved into happy arcs." + tail()),
 'sub': ("3:2", "One small chubby deep-sea research submarine seen exactly from the side, facing to the RIGHT: a short, fat, rounded white hull shaped like a fat egg lying on its side (about twice as long as it is tall) with a light-grey shade along its bottom, a short wide rounded bright orange-red tower on top of the hull in the middle (about a third of the hull length wide and a quarter of the hull height tall), the top of the tower is flat, level and completely plain (no lid, no hatch, no rail, nothing on top), two round windows with thick black rims and pale-blue glass on the front half of the hull, a small three-blade propeller inside a round ring at the back (LEFT) end, two short grey metal skids under the belly. No text, no numbers, no flags, no faces, no people, no cables. Whole submarine in frame with a margin. Bold clean thick outlines, big simple shapes, few details. " + OBJ + " " + KEY()),
 'props': ("3:2", "Three separate objects side by side in one row with wide empty gaps between them, drawn at the same scale, every object whole and in frame. LEFT: a big thick sandwich seen exactly from the side: two thick slices of soft white bread (#F6E7C1) with a golden-brown crust edge (#C98A3E), between them one thick pink bologna slice (#E9878F) and one wavy bright green lettuce leaf (#7CC242) peeking out at the edges; the sandwich is a square block a bit wider than it is tall, no bite marks, no toothpick, no plate. MIDDLE: a classic dome-topped metal lunchbox seen from the front, closed: bright red (#D93A2B) with a darker red shade, a rounded dome lid, a small silver latch in the middle of the front, a silver carrying handle on top. RIGHT: a small chubby round yellow fish (#F2C84B) with an orange shade, seen exactly from the side facing to the RIGHT, simple rounded fins and a rounded tail, one round white eye with a black dot pupil, no mouth line. No text, no labels. Bold clean thick outlines, big simple shapes, few details. Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border. " + KEY('magenta')),
 'ship': ("3:2", "The back half of a small white research ship seen exactly from the side, its back end (stern) on the RIGHT: a white hull with a dark navy-blue stripe along its top edge and a dark-red band along its bottom, the bottom edge of the hull is one straight horizontal line (the waterline: only the part above the water is drawn), a flat open back deck with a simple thin railing, a small white cabin with two square dark-blue windows on the LEFT part of the deck, and a tall bright orange A-frame crane standing at the very back of the deck and leaning out to the RIGHT past the stern, with a small black pulley wheel hanging under its top tip. No cables, no ropes, no people, no text, no numbers, no flags, no water, no waves. Whole ship part in frame with a margin. Bold clean thick outlines, big simple shapes, few details. " + OBJ + " " + KEY()),
 'bg': ("2:3", "A very simple open ocean seen exactly from the side, like a cutaway diagram. The top 35 % is a clear light-blue sky (#9ED3F0) with two small simple white clouds and no sun. At 35 % of the height a perfectly straight, flat, horizontal sea surface line runs across the whole width with a few small white wave crests on it. Below that line the water fills the rest of the picture in three flat horizontal colour bands that get darker with depth: bright blue (#3B8FD0) near the surface, then medium blue (#2A6FB0), then deep dark navy (#163A6B) at the bottom. No ships, no boats, no fish, no land, no rocks, no plants, no people. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# sunken-lunch - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
